        /// <summary>The baked size nearest <paramref name="pixels"/>.</summary>
        /// <remarks>
        /// Nearest rather than exact: DpiScale is continuous, so an exact match would need a bake per
        /// possible scale. Rows are drawn at the mask's own resolution and scaled by the caller, which
        /// is why picking the CLOSEST size matters -- a distant one scales visibly.
        /// </remarks>
        internal static Mask NearestSize(ImmutableArray<Mask> masks, float pixels)
        {
            var best = masks[0];
            var bestDelta = MathF.Abs(best.Size - pixels);
            foreach (var mask in masks)
            {
                var delta = MathF.Abs(mask.Size - pixels);
                if (delta < bestDelta)
                {
                    best = mask;
                    bestDelta = delta;
                }
            }
            return best;
        }
    }
